def followup_view(inputs, prior):
    packet=inputs.get('twentysecond_period_followup')
    if packet is None:return None
    if packet['version']!=1 or packet['content_digest']!=digest({k:v for k,v in packet.items()if k!='content_digest'}):raise ValueError('twentysecond period packet changed')
    if prior is None or prior['counts']['after']!=130 or packet['prior_digest']!=digest(prior):raise ValueError('twentysecond period prior changed')
    market=inputs['current_extension']['market_inputs']
    if packet['market_digest']!=digest(market):raise ValueError('twentysecond period market changed')
    sources={s['announcement_id']:s for s in packet['sources']}
    if len(sources)!=28 or len(packet['sources'])!=28 or set(sources)!=set(SOURCE_BINDINGS):raise ValueError('twentysecond period source set changed')
    if packet['visual_read']!=VISUAL:raise ValueError('twentysecond period visual scope changed')
    for aid,s in sources.items():
        if {k:s.get(k)for k in SOURCE_BINDINGS[aid]}!=SOURCE_BINDINGS[aid]or not s['protected_gate_passed']:raise ValueError('twentysecond period source binding changed')
        if s['published_on']>'2026-11-19':raise ValueError('twentysecond period future source')
        if set(s['selected_pages'])!={str(n)for n in range(1,s['pages']+1)}or len(s['page_hashes'])!=s['pages']:raise ValueError('twentysecond period pages missing')
        for n,t in s['selected_pages'].items():
            if sha256(t.encode()).hexdigest()!=s['page_hashes'][int(n)-1]:raise ValueError('twentysecond period page changed')
    for row in FINANCIAL:
        h,old,nine=D(row['h1_yuan']),D(row['prior_h1_yuan']),D(row['nine_month_yuan'])
        yoy=((h-old)/abs(old)*100).quantize(D('.01'),rounding=ROUND_HALF_UP)
        if row['h1_yoy_pct'] is not None and yoy!=D(row['h1_yoy_pct']):raise ValueError('twentysecond period H1 arithmetic changed')
        if row['reported_h1_yoy_pct']is not None and yoy!=D(row['reported_h1_yoy_pct']):raise ValueError('twentysecond period reported H1 changed')
        if nine-h!=D(row['quarter_yuan']):raise ValueError('twentysecond period quarter changed')
        if row['reported_quarter_yuan']is not None:
            delta=nine-h-D(row['reported_quarter_yuan'])
            if delta!=D(row['quarter_difference_yuan']):raise ValueError('twentysecond period preserved quarter difference changed')
            expected='direct_and_difference_checked'if delta==0 else 'reported_and_difference_conflict'
            if row['quarter_basis']!=expected:raise ValueError('twentysecond period quarter label changed')
        elif row['quarter_basis']!='nine_month_minus_h1':raise ValueError('twentysecond period derived quarter label changed')
        for aid,n,keys in [(row['h1_source'],row['h1_page'],['h1_yuan','prior_h1_yuan']),(row['q3_source'],row['q3_page'],['nine_month_yuan']+(['reported_quarter_yuan']if row['reported_quarter_yuan']is not None else []))]:
            text=sources[aid]['selected_pages'][str(n)].replace(',','').replace('\n','').replace(' ','').replace('−','-')
            if any(row[k]not in text for k in keys):raise ValueError('twentysecond period financial source changed')
    from st_regime_comparison import build
    windows=event_windows(market,build(market)['daily'],list(sources.values()),allow_nontraded=True,allow_missing=True)
    if digest(windows)!=packet['event_windows_digest']:raise ValueError('twentysecond period windows changed')
    conflicts=[(r['symbol'],r['metric'],r['quarter_difference_yuan'])for r in FINANCIAL if r['quarter_basis']=='reported_and_difference_conflict']
    if conflicts!=[('601718','revenue','40672.56'),('601718','parent_profit','38852.53'),('601718','recurring_profit','38952.53')]:raise ValueError('twentysecond preserved financial difference changed')
    result={'through': '2026-11-19', 'title': '程序通过、回款增加和单季转盈，判断应该怎样更新？', 'answer': '福成两项股东会程序通过，鉴证与年度审计仍待核；文峰信托本金回收增加，但旧诉讼计提与新立案分别看。际华最终处罚和特定差错鉴证落地，单季归母转正仍含非经常性收益，三项半年衔接差异保留；喜临门担保下降与占款增加并存，不当实收修复。', 'counts': {'files': 28, 'new_files': 28, 'reused_files': 0, 'pages': 838, 'new_pages': 838, 'viewed_pages': 24, 'initial_coverage': 130, 'complete_windows': 72, 'unfinished_windows': 12, 'stock_endpoint_gaps': 0}, 'boundary': '158条目录、28份838页中核24关键页，未认证全文或全部催化。84窗口72满12未满，76个股票端点核；48共同阶段。16财务9项直接差额一致、3项际华差异保留、4现金派生；11半年同比一致5不适用。披露仅精确到日期，非因果识别；重复月报不算独立验证，不晋级经验。', 'method_promotions': 0}
    result.update(chains=CHAINS,financial_bridge=FINANCIAL,phase_comparisons=PHASES,event_windows=windows,sources=[{k:v for k,v in s.items()if k not in ["raw_item","selected_pages","page_hashes"]}for s in sources.values()])
    return result
